import{_ as e,c as a,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const Z=JSON.parse('{"title":"常見問題","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/faq.md","filePath":"zh-TW/guide/faq.md","lastUpdated":1793163976000}'),r={name:"zh-TW/guide/faq.md"};function s(n,p,o,u,c,l){return t(),a("div",null,[...p[0]||(p[0]=[i('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><p>問：什麼是 NueZip？</p><p>答：NueZip 是一款專為 macOS 打造的專業壓縮檔管理工具，支援多種壓縮檔格式的壓縮與解壓縮，包括 RAR、ZIP、7-Zip、TAR、GZIP 和 BZIP2。</p><p>問：支援哪些 macOS 版本？</p><p>答：NueZip 需要 macOS 14 Sonoma 或更新版本，並針對 Apple Silicon（M 系列）晶片優化。</p><p>問：如何下載並安裝 NueZip？</p><p>答：請從 <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store</a>（推薦）下載，或從 <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 取得最新版本。</p><p>問：NueZip 是免費的嗎？</p><p>答：NueZip 提供具備核心功能的免費試用。一次性購買可解鎖完整功能集，包括批次操作、壓縮檔修復，以及進階加密。</p><p>問：支援哪些格式？</p><p>答：<strong>讀取</strong>：RAR、ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br><strong>寫入（壓縮）</strong>：ZIP、7-Zip、TAR、GZIP、BZIP2、XZ、Zstandard<br> 完整的格式對照表請參閱<a href="/zh-TW/guide/introduction.html">產品介紹</a>。</p><p>問：NueZip 可以建立 RAR 壓縮檔嗎？</p><p>答：不行。NueZip 可以 <strong>讀取</strong> RAR 壓縮檔（包括多分割卷與已修復的壓縮檔），但基於授權限制，不支援 RAR 壓縮。</p><p>問：NueZip 對機密檔案安全嗎？</p><p>答：安全。NueZip 完全在離線環境下運作。所有操作都在您的 Mac 本機上執行。受密碼保護的 ZIP 壓縮檔可使用 AES-256 加密。</p><p>問：NueZip 會將我的檔案上傳到雲端嗎？</p><p>答：不會。NueZip 是一款完全離線的應用程式。您的檔案絕不會被上傳到任何地方。壓縮或解壓縮都不需要網際網路連線。</p><p>問：如何更新 App？</p><p>答：請透過 Mac App Store（自動）更新，或從 GitHub Releases 下載最新版本。</p><p>問：如何回報錯誤或提出功能建議？</p><p>答：請在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub 儲存庫</a> 開立 issue。請包含您的 macOS 版本、NueZip 版本，以及重現步驟。</p><p>問：日誌與資料儲存在哪裡？</p><p>答：針對沙箱化（App Store）的建置版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Application Support/com.w3cub.nuezip/</span></span></code></pre></div><p>開發建置版本可能會將日誌寫入主控台。</p><p>若您需要更多解答，請在儲存庫中開立 issue，或查閱完整的文件。</p>',26)])])}const h=e(r,[["render",s]]);export{Z as __pageData,h as default};
